<template>
  <div class="tab-page">
    <el-form :inline="true" :model="query" size="small" class="filter-form">
      <el-form-item label="游戏名称"><el-input v-model="query.name" clearable /></el-form-item><el-form-item label="支持平台"><el-select v-model="query.platform" clearable><el-option v-for="item in platforms" :key="item" :label="item" :value="item" /></el-select></el-form-item>
      <el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /><el-option label="维护中" value="maintenance" /></el-select></el-form-item>
      <el-form-item label="游戏场馆"><el-select v-model="query.venueId" clearable filterable><el-option v-for="item in state.venues" :key="item.id" :label="item.nameZh" :value="item.id" /></el-select></el-form-item>
      <el-form-item label="场馆类型"><el-select v-model="query.venueType" clearable><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select></el-form-item>
      <el-form-item label="游戏CODE"><el-input v-model="query.code" clearable /></el-form-item><el-form-item label="品牌"><el-input v-model="query.brand" clearable /></el-form-item>
      <el-form-item><el-button type="primary" @click="search">筛选</el-button><el-button @click="resetQuery">重置</el-button></el-form-item>
    </el-form>
    <div class="toolbar"><el-button type="success" size="small" @click="openCreate">新增游戏</el-button><el-button type="primary" size="small" @click="openBatch">批量新增游戏</el-button></div>
    <el-table :data="page.rows" border stripe size="mini">
      <el-table-column type="index" label="序号" width="55" /><el-table-column prop="name" label="游戏名称" min-width="120" /><el-table-column label="游戏场馆" width="110"><template slot-scope="s">{{ venueName(s.row.venueId) }}</template></el-table-column><el-table-column label="场馆类型" width="90"><template slot-scope="s">{{ venueType(s.row.venueId) }}</template></el-table-column>
      <el-table-column prop="code" label="游戏CODE" width="110" /><el-table-column label="支持平台" min-width="120"><template slot-scope="s">{{ s.row.platforms.join(' / ') }}</template></el-table-column><el-table-column prop="sort" label="排序" width="60" />
      <el-table-column label="WEB游戏图片" width="105"><template slot-scope="s"><el-image class="thumb" :src="s.row.webImage" :preview-src-list="[s.row.webImage]" /></template></el-table-column><el-table-column label="H5游戏图片" width="100"><template slot-scope="s"><el-image class="thumb" :src="s.row.h5Image" :preview-src-list="[s.row.h5Image]" /></template></el-table-column>
      <el-table-column prop="authCount" label="授权数" width="70" /><el-table-column label="游戏状态" width="85"><template slot-scope="s"><el-tag size="mini" :type="s.row.status === 'enabled' ? 'success' : s.row.status === 'maintenance' ? 'warning' : 'info'">{{ statusLabel(s.row.status) }}</el-tag></template></el-table-column><el-table-column prop="brand" label="品牌" width="80" /><el-table-column prop="creator" label="创建人" width="90" /><el-table-column prop="createdAt" label="创建时间" width="150" /><el-table-column prop="editor" label="最后编辑人" width="100" /><el-table-column prop="editedAt" label="最后编辑时间" width="150" />
      <el-table-column label="操作" fixed="right" width="220"><template slot-scope="s"><el-button type="text" size="mini" @click="openEdit(s.row)">编辑</el-button><el-button type="text" size="mini" @click="toggleStatus(s.row)">切换状态</el-button><el-button type="text" size="mini" @click="changeAuth(s.row,1)">授权</el-button><el-button type="text" size="mini" @click="changeAuth(s.row,-1)">取消授权</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="page.total>0" :total="page.total" :page.sync="pageNum" :limit.sync="pageSize" @pagination="syncPage" />

    <el-dialog :title="editingId ? '编辑游戏' : '新增游戏'" :visible.sync="dialogVisible" width="660px" append-to-body><el-form :model="form" label-width="120px" size="small">
      <el-form-item label="游戏名称" required><el-input v-model.trim="form.name" /></el-form-item><el-form-item label="游戏场馆" required><el-select v-model="form.venueId" filterable class="full"><el-option v-for="item in state.venues" :key="item.id" :label="item.nameZh" :value="item.id" /></el-select></el-form-item><el-form-item label="场馆类型"><el-input :value="venueType(form.venueId)" disabled /></el-form-item><el-form-item label="游戏CODE" required><el-input v-model.trim="form.code" /></el-form-item>
      <el-form-item label="支持平台" required><el-checkbox-group v-model="form.platforms"><el-checkbox v-for="item in platforms" :key="item" :label="item" /></el-checkbox-group></el-form-item><el-form-item label="排序" required><el-input-number v-model="form.sort" :min="1" class="full" /></el-form-item>
      <el-form-item label="WEB游戏图片"><image-upload v-model="form.webImage" :limit="1" :file-size="2" :file-type="['jpg','jpeg','png']" :is-show-tip="false" :drag="false" replace-on-exceed /></el-form-item><el-form-item label="H5游戏图片"><image-upload v-model="form.h5Image" :limit="1" :file-size="2" :file-type="['jpg','jpeg','png']" :is-show-tip="false" :drag="false" replace-on-exceed /></el-form-item><el-form-item label="品牌"><el-input v-model.trim="form.brand" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio><el-radio label="maintenance">维护中</el-radio></el-radio-group></el-form-item>
    </el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></span></el-dialog>

    <el-dialog title="批量新增游戏" :visible.sync="batchVisible" width="1060px" append-to-body><el-button type="primary" size="mini" @click="addBatchRow">新增一行</el-button><el-table :data="batchRows" border size="mini" class="batch-table"><el-table-column label="游戏名称"><template slot-scope="s"><el-input v-model="s.row.name" /></template></el-table-column><el-table-column label="游戏场馆" width="150"><template slot-scope="s"><el-select v-model="s.row.venueId"><el-option v-for="v in state.venues" :key="v.id" :label="v.nameZh" :value="v.id" /></el-select></template></el-table-column><el-table-column label="游戏CODE"><template slot-scope="s"><el-input v-model="s.row.code" /></template></el-table-column><el-table-column label="支持平台" width="190"><template slot-scope="s"><el-select v-model="s.row.platforms" multiple><el-option v-for="p in platforms" :key="p" :label="p" :value="p" /></el-select></template></el-table-column><el-table-column label="排序" width="100"><template slot-scope="s"><el-input-number v-model="s.row.sort" :min="1" :controls="false" /></template></el-table-column><el-table-column label="品牌"><template slot-scope="s"><el-input v-model="s.row.brand" /></template></el-table-column><el-table-column label="操作" width="70"><template slot-scope="s"><el-button type="text" @click="batchRows.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table><span slot="footer"><el-button @click="batchVisible=false">取消</el-button><el-button type="primary" @click="submitBatch">提交</el-button></span></el-dialog>
  </div>
</template>

<script>
import ImageUpload from '@/components/ImageUpload'
const { TYPES, DEMO_IMAGE, cloneState, filterGames, paginate, validateGame, validateGameBatch, appendMaintenanceLog } = require('./model')
const emptyGame = () => ({ id: null, name: '', venueId: '', code: '', platforms: ['H5'], sort: 1, webImage: DEMO_IMAGE, h5Image: DEMO_IMAGE, authCount: 0, status: 'enabled', brand: '', creator: '演示管理员', createdAt: '', editor: '演示管理员', editedAt: '' })
export default { name:'GameList', components:{ImageUpload}, props:{state:{type:Object,required:true},presetVenueId:{type:[Number,String],default:''}}, data(){return{types:TYPES,platforms:['PC','H5','APP'],query:{name:'',platform:'',status:'',venueId:'',venueType:'',code:'',brand:''},appliedQuery:{},pageNum:1,pageSize:10,dialogVisible:false,batchVisible:false,editingId:null,form:emptyGame(),batchRows:[]}}, watch:{presetVenueId:{immediate:true,handler(value){if(value){this.query.venueId=value;this.search()}}}}, computed:{enrichedGames(){return this.state.games.map(row=>({...row,venueType:this.venueType(row.venueId)}))},page(){return paginate(filterGames(this.enrichedGames,this.appliedQuery),this.pageNum,this.pageSize)}}, methods:{venue(rowId){return this.state.venues.find(v=>v.id===rowId)},venueName(id){return(this.venue(id)||{}).nameZh||'-'},venueType(id){return(this.venue(id)||{}).type||'-'},statusLabel(v){return({enabled:'启用',disabled:'停用',maintenance:'维护中'})[v]},search(){this.appliedQuery=cloneState(this.query);this.pageNum=1},resetQuery(){this.query={name:'',platform:'',status:'',venueId:'',venueType:'',code:'',brand:''};this.search()},syncPage({page,limit}){this.pageNum=page;this.pageSize=limit},openCreate(){this.editingId=null;this.form=emptyGame();this.dialogVisible=true},openEdit(row){this.editingId=row.id;this.form=cloneState(row);this.dialogVisible=true},stamp(row){const time=new Date().toISOString().slice(0,19).replace('T',' ');row.editedAt=time;row.editor='演示管理员';if(!row.createdAt)row.createdAt=time},submit(){const r=validateGame(this.form,this.state.games,this.editingId);if(!r.valid)return this.$message.warning(r.message);this.stamp(this.form);if(this.editingId)Object.assign(this.state.games.find(i=>i.id===this.editingId),cloneState(this.form));else{this.form.id=Math.max(0,...this.state.games.map(i=>Number(i.id)))+1;this.state.games.unshift(cloneState(this.form))}this.$emit('state-change');this.dialogVisible=false;this.$modal.msgSuccess('游戏保存成功')},openBatch(){this.batchRows=[emptyGame()];this.batchVisible=true},addBatchRow(){this.batchRows.push(emptyGame())},submitBatch(){const r=validateGameBatch(this.batchRows,this.state.games);if(!r.valid)return this.$message.warning(r.message);let next=Math.max(0,...this.state.games.map(i=>Number(i.id)))+1;this.batchRows.forEach(row=>{row.id=next++;this.stamp(row);this.state.games.unshift(cloneState(row))});this.$emit('state-change');this.batchVisible=false;this.$modal.msgSuccess('批量新增游戏成功')},toggleStatus(row){const next=row.status==='enabled'?'maintenance':row.status==='maintenance'?'disabled':'enabled';this.$confirm(`确认切换为${this.statusLabel(next)}？`,'提示').then(()=>{row.status=next;this.stamp(row);if(next==='maintenance')appendMaintenanceLog(this.state,{venueId:row.venueId,gameId:row.id,reason:'游戏切换维护状态'});this.$emit('state-change');this.$modal.msgSuccess('游戏状态已更新')}).catch(()=>{})},changeAuth(row,d){if(d<0&&row.authCount<=0)return this.$message.warning('当前没有可取消的授权');row.authCount=Math.max(0,row.authCount+d);this.$emit('state-change');this.$modal.msgSuccess(d>0?'授权成功':'取消授权成功')}}}
</script>
<style scoped>.filter-form{padding-top:10px}.filter-form .el-input,.filter-form .el-select{width:170px}.toolbar{margin-bottom:10px}.thumb{width:38px;height:38px}.full{width:100%}.batch-table{margin-top:10px}</style>
